package com.example.leavemanagement.integration;
import com.example.leavemanagement.audit.persistence.*;import com.example.leavemanagement.balance.application.*;import com.example.leavemanagement.balance.persistence.*;import com.example.leavemanagement.people.persistence.*;import com.example.leavemanagement.policy.persistence.*;import com.example.leavemanagement.shared.api.DomainException;import com.example.leavemanagement.shared.security.*;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class BalanceAdministrationTest {private final LeaveBalanceRepository balances=mock(LeaveBalanceRepository.class);private final LeaveBalanceMovementRepository movements=mock(LeaveBalanceMovementRepository.class);private final AuditEventRepository audits=mock(AuditEventRepository.class);private final EmployeeProfileRepository employees=mock(EmployeeProfileRepository.class);private final LeaveTypeRepository types=mock(LeaveTypeRepository.class);private final CurrentActorProvider actors=mock(CurrentActorProvider.class);private final UUID admin=UUID.randomUUID();@BeforeEach void setup(){when(actors.require()).thenReturn(new CurrentActor(admin,UUID.randomUUID(),null,Set.of("ADMINISTRATOR"),"Admin"));}
 @Test void allocationCreatesLedgerAndAudit(){var employee=UUID.randomUUID();var type=LeaveTypeEntity.create(UUID.randomUUID(),"ANNUAL","Annual",null,true);when(employees.findById(employee)).thenReturn(Optional.of(mock(EmployeeProfileEntity.class)));when(types.findById(type.getId())).thenReturn(Optional.of(type));when(balances.save(any())).thenAnswer(inv->inv.getArgument(0));var service=new BalanceAllocationService(balances,movements,audits,employees,types,actors);var view=service.allocate(employee,new BalanceAllocationService.Command(type.getId(),LocalDate.now(),LocalDate.now().plusDays(30),5,"Opening allocation"),"allocate-1");assertThat(view.entitledDays()).isEqualTo(5);verify(movements).save(any());verify(audits).save(any());}
 @Test void staleAdjustmentDoesNotMutate(){var b=LeaveBalanceEntity.allocate(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),LocalDate.now(),LocalDate.now().plusDays(10),4,Instant.now());when(balances.findLockedById(b.getId())).thenReturn(Optional.of(b));var service=new BalanceAdjustmentService(balances,movements,audits,types,actors);assertThatThrownBy(()->service.adjust(b.getId(),new BalanceAdjustmentService.Command(1,"Reason",3),"adjust-1")).isInstanceOf(DomainException.class).hasMessageContaining("changed");verifyNoInteractions(movements,audits);}
 @Test void adjustmentRequiresReasonAndIsAudited(){var b=LeaveBalanceEntity.allocate(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),LocalDate.now(),LocalDate.now().plusDays(10),4,Instant.now());when(balances.findLockedById(b.getId())).thenReturn(Optional.of(b));var service=new BalanceAdjustmentService(balances,movements,audits,types,actors);when(types.findById(b.getLeaveTypeId())).thenReturn(Optional.of(LeaveTypeEntity.create(b.getLeaveTypeId(),"A","Annual",null,true)));assertThatThrownBy(()->service.adjust(b.getId(),new BalanceAdjustmentService.Command(1,"",0),"adjust-2")).isInstanceOf(DomainException.class);service.adjust(b.getId(),new BalanceAdjustmentService.Command(1,"Correction",0),"adjust-3");assertThat(b.getAdjustmentUnits()).isEqualTo(2);verify(audits).save(any());}
}
